node -e "
const R = 3958.8; // Earth's radius in miles
const toRad = d => d * Math.PI / 180;

const lat1 = 37.7749, lon1 = -122.4194; // San Francisco
const lat2 = 42.3396, lon2 = -71.0640;  // Boston, MA 02118

const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));
const miles = R * c;
const km = miles * 1.60934;

console.log('=== Distance Estimate ===');
console.log('From:  (37.7749, -122.4194) — San Francisco, CA');
console.log('To:    4829 Elm Ridge Way, Suite 7, Boston, MA 02118, USA');
console.log('       (approx. coords: 42.3396, -71.0640)');
console.log('');
console.log('Straight-line (as the crow flies):');
console.log('  ' + miles.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' miles');
console.log('  ' + km.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' km');
console.log('');
console.log('Estimated driving distance (~15-30% longer):');
console.log('  ~' + Math.round(miles*1.2).toLocaleString() + '–' + Math.round(miles*1.3).toLocaleString() + ' miles');
console.log('  ~' + Math.round(km*1.2).toLocaleString() + '–' + Math.round(km*1.3).toLocaleString() + ' km');
"
